// Ahora los datos llegan directamente en msg.payload
const datos_viento = msg.payload;

// Validamos que haya datos para procesar
if (datos_viento.length === 0) return null;

// 1. Definimos las etiquetas de las 16 direcciones
const direcciones = ['N', 'NNE', 'NE', 'ENE', 'E', 'ESE', 'SE', 'SSE', 'S', 'SSO', 'SO', 'OSO', 'O', 'ONO', 'NO', 'NNO'];

// 2. Definimos nuestras "cubetas" de velocidad
const rangos = [
    { max: 0.5, name: '0 - 0.5 m/s', data: new Array(16).fill(0) },
    { max: 1, name: '0.5 - 1 m/s', data: new Array(16).fill(0) },
    { max: 1.5, name: '1 - 1.5 m/s', data: new Array(16).fill(0) },
    { max: 2, name: '1.5 - 2 m/s', data: new Array(16).fill(0) },
    { max: 999, name: '> 2 m/s', data: new Array(16).fill(0) }
];

// 3. Clasificamos cada lectura
// Ahora recorremos el array de objetos directamente
datos_viento.forEach((lectura) => {
    // Extraemos la velocidad y dirección del MISMO objeto
    let vel = lectura.Velocidad_Viento;
    let dir = lectura.Direccion_Viento;

    // Si por alguna razón un dato viene vacío, lo saltamos para evitar errores
    if (vel == null || dir == null) return; 

    // Matemáticas para saber a qué sector pertenece (cada sector mide 22.5 grados)
    let dirIndex = Math.floor(((dir + 11.25) % 360) / 22.5);

    // Buscamos en qué rango de velocidad cae y le sumamos 1 a su contador
    for (let i = 0; i < rangos.length; i++) {
        // (Corregido: era rangos[i].max, no rangos.max)
        if (vel <= rangos[i].max) {
            rangos[i].data[dirIndex]++;
            break;
        }
    }
});

// 4. Calculamos el total de datos que llegaron
const totalDatos = datos_viento.length;

// 5. Preparamos las series en el formato que exige ECharts para barras apiladas
const seriesList = rangos.map(rango => {
    return {
        name: rango.name,
        type: 'bar',
        coordinateSystem: 'polar',
        stack: 'viento',
        data: rango.data.map(conteo => {
            return ((conteo / totalDatos) * 100).toFixed(2);
        })
    };
});

// Enviamos al gráfico las direcciones y las series ya listas
msg.payload = {
    categorias: direcciones,
    series: seriesList
};

return msg;

